function pdfZ(f){if(!PV.el)return;const r=PV.el.getBoundingClientRect();commitZoom(f,r.left+r.width/2,r.top+r.height/2)}
const pdfZoomBtns=d=>d.kind=='pdf'&&!S.pdfText?`<button onclick="pdfZ(.8)">${I('minus')}</button><button onclick="pdfZ(1.25)">${I('plus')}</button>`:'';

async function outlineIdx(pdf,sents){const out=[];try{const ol=await pdf.getOutline();if(!ol)return out;const walk=async(arr,lv)=>{for(const o of arr){try{let d=o.dest;if(typeof d=='string')d=await pdf.getDestination(d);if(Array.isArray(d)&&o.title&&lv<=4){const pg=await pdf.getPageIndex(d[0]),f=sents.find(q=>q[0]==pg);out.push({lv,t:o.title.trim(),pg,s:f?f[1]:0})}}catch(e){}if(o.items&&o.items.length)await walk(o.items,lv+1)}};await walk(ol,1)}catch(e){}return out.slice(0,200)}
function headingGuess(pages){const hs=[];pages.forEach(p=>p.items.forEach(it=>hs.push(it[3])));if(!hs.length)return[];hs.sort((a,b)=>a-b);const med=hs[hs.length>>1],out=[];
 pages.forEach((p,n)=>{let cur=null;const flush=()=>{if(cur){const t=p.text.slice(cur.s,cur.e).replace(/\s+/g,' ').trim();if(cur.h>=med*1.22&&t.length>2&&t.length<110&&!/[.;,:]$/.test(t)&&/[A-Za-zÀ-ÿ]{3}/.test(t))out.push({t,pg:n,s:cur.s,h:Math.round(cur.h*2)/2});cur=null}};
  p.items.forEach(([x,y,w,h,s,e,ff,fur])=>{if(fur)return;if(cur&&Math.abs(cur.y-y)<h*.6){cur.e=e;cur.h=Math.max(cur.h,h)}else{flush();cur={y,s,e,h}}});flush()});
 const cnt={};out.forEach(o=>cnt[o.t]=(cnt[o.t]||0)+1);const ok=out.filter(o=>cnt[o.t]<3),sizes=[...new Set(ok.map(o=>o.h))].sort((a,b)=>b-a);
 return ok.slice(0,80).map(o=>({lv:Math.min(sizes.indexOf(o.h)+1,4),t:o.t,pg:o.pg,s:o.s}))}

async function reanalyze(id){const d=S.docs.find(o=>o.id==id),buf=await idbGet('f'+id);if(!d||!buf){S.modal=null;render();return tell('File PDF non trovato su questo dispositivo.')}
 S.modal='file';S.busy=true;S.msg='Analisi del PDF…';render();
 try{const r=await readPdf(buf,d.title);if(K())await aiMeta(r);await idbSet('m'+id,r.model);if(r.thumb)await idbSet('t'+id,r.thumb);d.pages=r.pages;if(!(d.authors||[]).length&&r.authors.length)d.authors=r.authors;if(!d.year&&r.year)d.year=r.year;
  if(r.idx.length&&!(d.idx||[]).length)d.idx=r.idx.map((x,k)=>({id:id+k,lv:x.lv,t:x.t,pg:x.pg,s:x.s,i:Math.max(0,r.model.sents.findIndex(q=>q[0]==x.pg&&q[2]>x.s))}));
  delete PS[id];delete PL[id];PV.id=null;PV.th=null;d.kind='pdf';save();S.busy=false;S.msg=null;S.modal=null;render();tell('PDF rianalizzato.')}catch(e){S.busy=false;S.msg=null;S.modal=null;render();tell('Errore: '+e.message)}}

function charAtPos(n,px,py){const pm=PM.pages[n];let best=null,bd=1e9;for(const it of pm.items){const[x,y,w,h,s,e]=it,dy=Math.abs(y+h/2-py);if(dy<h*.7&&px>=x-2&&px<=x+w+2){let lo=s,hi=e;while(lo<hi){const mid=(lo+hi)>>1;if(xAt(it,pm.text,mid)<px)lo=mid+1;else hi=mid}return lo}if(dy<bd){bd=dy;best=it}}return best?best[4]:0}
function calcPos(){try{const s=getSelection();if(!s.rangeCount)return null;const r=s.getRangeAt(0),t=s.toString().replace(/\s+/g,' ').trim(),el=r.startContainer.nodeType==1?r.startContainer:r.startContainer.parentElement;if(!t||!el)return null;
 const tl=el.closest('.textLayer');if(tl&&PM){const w=tl.closest('.pgw'),n=+w.dataset.pg,rc=r.getClientRects()[0]||r.getBoundingClientRect(),wb=w.getBoundingClientRect(),k=charAtPos(n,(rc.left-wb.left)/PV.scale+1,(rc.top+rc.height/2-wb.top)/PV.scale),text=PM.pages[n].text,rg=new RegExp(t.split(' ').map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('\\s+'),'g');rg.lastIndex=Math.max(0,k-3);let q=rg.exec(text);if(!q){rg.lastIndex=0;q=rg.exec(text)}return q?{pg:n,s:q.index,e:q.index+q[0].length}:null}
 const sp=el.closest('.s');if(sp){const k=+sp.dataset.k,pre=document.createRange();pre.setStart(sp,0);pre.setEnd(r.startContainer,r.startOffset);const o=pre.toString().length,len=Math.max(1,Math.min(t.length,sp.textContent.length-o)),sn=sents(doc())[k];return sn&&sn.pg!=null?{pg:sn.pg,s:sn.s+o,e:sn.s+o+len}:{k,o,len}}}catch(e){}return null}
const HC=['rgba(255,214,0,.42)','rgba(70,200,255,.42)','rgba(175,125,255,.45)','rgba(110,220,140,.42)','rgba(255,125,175,.42)'];
function markSent(s,k,d){if(S.showsel===false)return esc(s.t);const m=[],add=(w,cl,col)=>{if(w.pg!=null&&s.pg!=null){if(w.pg==s.pg&&w.s>=s.s&&w.e<=s.e+1)m.push([w.s-s.s,w.e-s.s,cl,col])}else if(w.pg==null&&w.k===k)m.push([w.o,w.o+w.len,cl,col])};(d.hi||[]).forEach(w=>add(w,'hc'+w.c));d.kw.forEach(w=>add(w,'kw',kcol(w)));m.sort((a,b)=>a[0]-b[0]);let o='',p=0;for(const[a,b,cl,col]of m){if(a<p)continue;o+=esc(s.t.slice(p,a))+'<mark class="'+cl+'"'+(col?' style="background:'+rgba(col,.35)+';color:#fff"':'')+'>'+esc(s.t.slice(a,b))+'</mark>';p=b}return o+esc(s.t.slice(p))}
function legacyKw(d){let ch=0;d.kw=(d.kw||[]).map(k=>{if(typeof k!='string'&&!k.leg)return k;const t=typeof k=='string'?k:k.t,o={id:Date.now()+Math.floor(Math.random()*1e6),t},lc=t.toLowerCase();
 if(d.kind=='pdf'&&PM&&PV.id==d.id){for(let n=0;n<PM.pages.length;n++){const i=PM.pages[n].text.toLowerCase().indexOf(lc);if(i>=0){o.pg=n;o.s=i;o.e=i+t.length;ch=1;return o}}}
 else if(d.kind!='pdf'){const L=sents(d);for(let q=0;q<L.length;q++){const i=L[q].t.toLowerCase().indexOf(lc);if(i>=0){o.k=q;o.o=i;o.len=t.length;ch=1;return o}}}
 o.leg=1;return o});if(ch)save()}

function lineBoxes(R){const L=[];for(const r of R.slice().sort((a,b)=>a.y-b.y||a.x-b.x)){const l=L.find(z=>Math.abs(z.y-r.y)<r.h*.5&&r.x<=z.x1+3*r.h&&r.x+r.w>=z.x0-3*r.h);if(l){l.x0=Math.min(l.x0,r.x);l.x1=Math.max(l.x1,r.x+r.w);l.h=Math.max(l.h,r.h)}else L.push({x0:r.x,x1:r.x+r.w,y:r.y,h:r.h})}
 L.sort((a,b)=>a.y-b.y);L.forEach(l=>{l.t=l.y-1.5;l.bt=l.y+l.h+1.5});for(let i=0;i<L.length-1;i++){const a=L[i],b=L[i+1],gap=b.y-(a.y+a.h);if(gap>-a.h*.5&&gap<a.h*1.8){const mid=a.y+a.h+gap/2;a.bt=mid;b.t=mid}}return L}

/* intestazioni, piè di pagina e numeri di pagina non fanno parte del testo da seguire */
function markFurniture(pages){const N=pages.length,sig=new Map(),lines=pages.map(p=>{const L=[];for(const it of p.items){const l=L[L.length-1],t=p.text.slice(it[4],it[5]);if(l&&Math.abs(l.y-it[1])<it[3]*.5){l.its.push(it);l.t+=t}else L.push({y:it[1],h:it[3],t,its:[it]})}return L});
 let lat=0,rtl=0;pages.forEach(p=>{lat+=(p.text.match(/[A-Za-zÀ-ÿ]/g)||[]).length;rtl+=(p.text.match(/[\u0590-\u08FF]/g)||[]).length});const latinDoc=lat>rtl*2;
 lines.forEach((L,n)=>{const H=pages[n].h;L.forEach(l=>{const top=l.y/H,bot=(l.y+l.h)/H;l.strict=top<.085||bot>.915;l.wide=top<.2||bot>.85;l.band=top<.14||bot>.88;if(l.band){l.sig=l.t.replace(/\d+/g,'#').replace(/\s+/g,' ').trim().toLowerCase();if(l.sig){const s=sig.get(l.sig)||new Set();s.add(n);sig.set(l.sig,s)}}})});
 const hs=[];pages.forEach(p=>p.items.forEach(it=>hs.push(it[3])));hs.sort((a,b)=>a-b);const med=hs[hs.length>>1]||10,need=Math.max(2,Math.ceil(N*.3));
 lines.forEach(L=>L.forEach(l=>{const t=l.t.trim();if(!t)return;
  const num=l.strict&&/^[\s\-–—.·•]*(pag(ina)?\.?\s*)?\d{1,4}(\s*(\/|di|of)\s*\d{1,4})?[\s\-–—.·•]*$/i.test(t),
   web=l.wide&&/(www\.|https?:|doi\.org|doi:|@[\w-]+\.\w{2,})/i.test(t),
   rt=l.wide&&latinDoc&&(t.match(/[\u0590-\u08FF]/g)||[]).length>=Math.max(3,(t.match(/\p{L}/gu)||[]).length*.6),
   rep=l.band&&l.sig&&N>=2&&(sig.get(l.sig)||new Set()).size>=need&&l.h<=med*1.2;
  if(num||web||rt||rep)l.its.forEach(it=>{it[7]=1})}))}
function blankFur(pm){const t=pm.text;let o='',p=0;for(const it of pm.items){if(!it[7])continue;o+=t.slice(p,it[4])+' '.repeat(it[5]-it[4]);p=it[5]}return o+t.slice(p)}
